import { useEffect, useState, useContext } from 'react';
import axios from 'axios';
import { useSearchParams } from 'react-router-dom';
import Result from '../components/Result';
import AuthContext from '../context/AuthContext';

function History() {
  const [resumes, setResumes] = useState([]);
  const [page, setPage] = useState(1);
  const [pages, setPages] = useState(1);
  const [total, setTotal] = useState(0);
  const [loading, setLoading] = useState(false);
  const [searchParams] = useSearchParams();
  const initialJobId = searchParams.get('jobId') || '';

  const [filters, setFilters] = useState({
    from: '',
    to: '',
    minScore: '',
    q: '',
    limit: 10,
    jobId: initialJobId
  });

  const [openId, setOpenId] = useState(null);
  const [currentEdit, setCurrentEdit] = useState({});
  const { user } = useContext(AuthContext);

  const STATUS_OPTIONS = ['Not Reviewed', 'Shortlisted', 'Rejected', 'Interview Scheduled', 'Interviewed', 'Offer Extended', 'Hired'];

  useEffect(() => {
    load();
  }, [page, filters]);

  async function load() {
    setLoading(true);
    try {
      const params = { page, limit: filters.limit };
      if (filters.minScore) params.minScore = filters.minScore;
      if (filters.from) params.from = filters.from;
      if (filters.to) params.to = filters.to;
      if (filters.q) params.q = filters.q;
      if (filters.jobId) params.jobId = filters.jobId;

      const res = await axios.get('/api/resume/my', { params, withCredentials: true });
      setResumes(res.data.data);
      setTotal(res.data.total || res.data.data?.length || 0);
      setPages(res.data.pages || 1);
      setOpenId(null);
      setCurrentEdit({});
    } catch (err) {
      console.error('Load error:', err);
      alert('Failed to load history');
    } finally {
      setLoading(false);
    }
  }

  async function updateStatus(id, newStatus, note = '') {
    try {
      const payload = { status: newStatus, note: note || 'Quick action' };
      const res = await axios.post(`/api/resume/${id}/status`, payload, { withCredentials: true });
      const updated = res.data.data;
      setResumes(prev => prev.map(r => r._id === id ? updated : r));
    } catch (err) {
      console.error('Status update error:', err);
      alert('Failed to update status');
    }
  }

  function getRecommendation(score) {
    if (score >= 85) return { label: 'Top Pick', class: 'score-good' };
    if (score >= 70) return { label: 'Highly Recommended', class: 'bg-primary' };
    if (score >= 50) return { label: 'Potential Match', class: 'score-warn' };
    return { label: 'Low Match', class: 'score-bad' };
  }

  return (
    <div className="page mt-10">
      <div className="container">
        <header className="flex justify-between items-center mb-6">
          <div>
            <h2 className="text-2xl">Application History</h2>
            <p className="muted">Ranking candidates by match score and qualifications.</p>
          </div>
          {user && ['recruiter', 'admin'].includes(user.role) && (
            <span className="badge bg-primary">Recruiter Mode</span>
          )}
        </header>

        {/* Filters Card */}
        <div className="card mb-6 p-6">
          <div className="grid grid-cols-1 md:grid-cols-5 gap-4">
            <div className="form-group mb-0">
              <label className="form-label">Min Score</label>
              <input
                type="number"
                className="form-input"
                placeholder="0"
                value={filters.minScore}
                onChange={e => setFilters(f => ({ ...f, minScore: e.target.value }))}
              />
            </div>
            <div className="form-group mb-0">
              <label className="form-label">From Date</label>
              <input
                type="date"
                className="form-input"
                value={filters.from}
                onChange={e => setFilters(f => ({ ...f, from: e.target.value }))}
              />
            </div>
            <div className="form-group mb-0">
              <label className="form-label">Search</label>
              <input
                type="text"
                className="form-input"
                placeholder="Skills, name..."
                value={filters.q}
                onChange={e => setFilters(f => ({ ...f, q: e.target.value }))}
              />
            </div>
            <div className="flex items-end gap-2">
              <button onClick={() => setPage(1)} className="btn btn-primary w-full">Filter</button>
            </div>
            <div className="flex items-end gap-2">
              <button onClick={() => setFilters({ from: '', to: '', minScore: '', q: '', limit: 10, jobId: '' })} className="btn btn-ghost w-full">Reset</button>
            </div>
          </div>
        </div>

        {loading ? (
          <div className="text-center py-10"><p className="muted">Ranking candidates...</p></div>
        ) : (
          <div className="flex flex-col gap-4">
            <div className="mb-2"><strong className="muted">{total} Applications Found</strong></div>

            {resumes.map((r, index) => {
              const rec = getRecommendation(r.score || 0);
              return (
                <div key={r._id} className="card p-6 hover-shadow transition-all">
                  <div className="flex justify-between items-start">
                    <div className="flex-1">
                      <div className="flex items-center gap-3 mb-2">
                        <span className="text-lg font-bold">#{index + 1 + (page - 1) * filters.limit} {r.fileName?.split('-')[1] || 'Candidate'}</span>
                        <span className={`badge ${rec.class}`}>{rec.label}</span>
                        {r.jobId?.title && <span className="badge bg-secondary">Job: {r.jobId.title}</span>}
                      </div>

                      <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-4">
                        <div>
                          <strong className="block text-sm muted mb-1">Match Score</strong>
                          <div className="text-xl font-extrabold" style={{ color: r.score >= 70 ? 'var(--success)' : (r.score >= 40 ? '#f59e0b' : 'var(--danger)') }}>
                            {Math.round(r.score || 0)}%
                          </div>
                        </div>
                        <div className="md:col-span-2">
                          <strong className="block text-sm muted mb-1">Key Matches</strong>
                          <div className="flex flex-wrap gap-1">
                            {(r.matchedSkills || []).slice(0, 5).map((s, i) => (
                              <span key={i} className="badge bg-secondary">{s}</span>
                            ))}
                            {(r.matchedSkills || []).length > 5 && <span className="text-sm muted">+{r.matchedSkills.length - 5} more</span>}
                          </div>
                        </div>
                      </div>

                      <div className="flex items-center gap-4">
                        <span className={`badge ${r.interviewStatus === 'Shortlisted' ? 'bg-success' : (r.interviewStatus === 'Rejected' ? 'bg-danger' : 'bg-secondary')}`}>
                          Status: {r.interviewStatus}
                        </span>
                        <span className="text-sm muted">{new Date(r.createdAt).toLocaleDateString()}</span>
                      </div>
                    </div>

                    <div className="flex flex-col gap-2">
                      <button className="btn btn-ghost" onClick={() => setOpenId(openId === r._id ? null : r._id)}>
                        {openId === r._id ? 'Close Details' : 'View Full Analysis'}
                      </button>

                      {['recruiter', 'admin'].includes(user?.role) && r.interviewStatus === 'Not Reviewed' && (
                        <div className="flex gap-2">
                          <button className="btn btn-success" style={{ padding: '8px 12px' }} onClick={() => updateStatus(r._id, 'Shortlisted')}>Shortlist</button>
                          <button className="btn btn-danger" style={{ padding: '8px 12px' }} onClick={() => updateStatus(r._id, 'Rejected')}>Reject</button>
                        </div>
                      )}
                    </div>
                  </div>

                  {openId === r._id && (
                    <div className="mt-8 border-t pt-6">
                      <Result data={r} />

                      <div className="mt-6 p-4 bg-slate-50 rounded-lg">
                        <h4 className="text-sm font-bold mb-3 uppercase tracking-wider">Recruiter Actions</h4>
                        <div className="flex flex-wrap gap-4 items-end">
                          <div className="form-group mb-0">
                            <label className="form-label">Application Status</label>
                            <select className="form-input" value={currentEdit.status || r.interviewStatus} onChange={e => setCurrentEdit({ ...currentEdit, status: e.target.value })}>
                              {STATUS_OPTIONS.map(s => <option key={s} value={s}>{s}</option>)}
                            </select>
                          </div>
                          <div className="form-group mb-0">
                            <label className="form-label">Interview Date</label>
                            <input type="date" className="form-input" />
                          </div>
                          <button className="btn btn-primary" onClick={() => updateStatus(r._id, currentEdit.status)}>Update Profile</button>
                        </div>
                      </div>
                    </div>
                  )}
                </div>
              );
            })}

            {/* Pagination */}
            <div className="flex justify-center gap-4 mt-8">
              <button className="btn btn-ghost" disabled={page === 1} onClick={() => setPage(p => p - 1)}>Previous</button>
              <div className="flex items-center px-4 font-bold text-primary">Page {page} of {pages}</div>
              <button className="btn btn-ghost" disabled={page === pages} onClick={() => setPage(p => p + 1)}>Next</button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

export default History;
